//! Portable annotation definitions. Values are regenerated by the CAD worker;
//! unresolved semantic anchors remain broken records, never stale measurements.
use crate::{Core, Draft, Error, Inputs, Job, Result, hash, id};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum GeometryKind {
    Face,
    Edge,
}
#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GeometryRef {
    pub entity_kind: GeometryKind,
    pub format: String,
    pub sha256: String,
}
impl GeometryRef {
    fn validate(&self) -> Result<()> {
        if self.format != "occt-brep-v3-no-display-v1" || !crate::portable::valid_hash(&self.sha256)
        {
            return Err(Error::domain(
                "INVALID_REQUEST",
                "Invalid geometry anchor fingerprint",
            ));
        }
        Ok(())
    }
}
#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum CircleMeasure {
    Radius,
    Diameter,
}
#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Anchor {
    LocalPoint {
        instance_id: String,
        point: [f64; 3],
    },
    Bounds {
        instance_id: String,
        fraction: [f64; 3],
    },
    FeatureCenter {
        instance_id: String,
        feature: String,
    },
    GeometryCenter {
        instance_id: String,
        entity: GeometryRef,
    },
}
#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum Axis {
    X,
    Y,
    Z,
}
#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Definition {
    Distance {
        start: Anchor,
        end: Anchor,
    },
    Angle {
        start: Anchor,
        vertex: Anchor,
        end: Anchor,
    },
    Overall {
        instance_id: String,
        axis: Axis,
    },
    Radius {
        instance_id: String,
        feature: String,
    },
    Diameter {
        instance_id: String,
        feature: String,
    },
    Published {
        publication_id: String,
    },
    GeometryCircle {
        instance_id: String,
        entity: GeometryRef,
        measure: CircleMeasure,
    },
}
#[derive(Clone, Debug, Default, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum DisplayUnit {
    #[default]
    Mm,
    Cm,
    M,
    In,
    Deg,
    Rad,
}
#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Format {
    pub unit: DisplayUnit,
    pub precision: u8,
}
impl Default for Format {
    fn default() -> Self {
        Self {
            unit: DisplayUnit::Mm,
            precision: 2,
        }
    }
}
#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Annotation {
    pub id: String,
    pub label: String,
    pub definition: Definition,
    #[serde(default)]
    pub format: Format,
    #[serde(default)]
    pub parameter: Option<String>,
    #[serde(default)]
    pub label_offset: [f64; 2],
}
fn identifier(value: &str) -> Result<()> {
    if value.is_empty() || value.len() > 256 || value.chars().any(char::is_control) {
        return Err(Error::domain(
            "INVALID_REQUEST",
            "Invalid annotation identifier",
        ));
    }
    Ok(())
}
impl Anchor {
    fn validate(&self) -> Result<()> {
        let anchor = self;
        match anchor {
            Anchor::GeometryCenter {
                instance_id,
                entity,
            } => {
                identifier(instance_id)?;
                entity.validate()?;
            }
            Anchor::FeatureCenter {
                instance_id,
                feature,
            } => {
                identifier(instance_id)?;
                identifier(feature)?;
            }
            Anchor::LocalPoint { instance_id, point } => {
                identifier(instance_id)?;
                if point.iter().any(|v| !v.is_finite()) {
                    return Err(Error::domain("INVALID_REQUEST", "Non-finite local anchor"));
                }
            }
            Anchor::Bounds {
                instance_id,
                fraction,
            } => {
                identifier(instance_id)?;
                if fraction
                    .iter()
                    .any(|v| !v.is_finite() || !(0. ..=1.).contains(v))
                {
                    return Err(Error::domain(
                        "INVALID_REQUEST",
                        "Bounds anchors require fractions in [0, 1]",
                    ));
                }
            }
        }
        Ok(())
    }
}
impl Annotation {
    pub fn validate(&self) -> Result<()> {
        identifier(&self.id)?;
        identifier(&self.label)?;
        if self.format.precision > 6
            || self
                .label_offset
                .iter()
                .any(|v| !v.is_finite() || v.abs() > 4096.)
        {
            return Err(Error::domain(
                "INVALID_REQUEST",
                "Invalid annotation presentation",
            ));
        }
        if let Some(parameter) = &self.parameter {
            identifier(parameter)?;
        }
        let angular = matches!(self.format.unit, DisplayUnit::Deg | DisplayUnit::Rad);
        if !matches!(self.definition, Definition::Published { .. })
            && angular != matches!(self.definition, Definition::Angle { .. })
        {
            return Err(Error::domain(
                "INVALID_REQUEST",
                "Angles require deg/rad display units; lengths require mm/cm/m/in",
            ));
        }
        match &self.definition {
            Definition::Published { publication_id } => identifier(publication_id)?,
            Definition::Overall { instance_id, .. } => identifier(instance_id)?,
            Definition::GeometryCircle {
                instance_id,
                entity,
                ..
            } => {
                identifier(instance_id)?;
                entity.validate()?;
            }
            Definition::Radius {
                instance_id,
                feature,
            }
            | Definition::Diameter {
                instance_id,
                feature,
            } => {
                identifier(instance_id)?;
                identifier(feature)?;
            }
            Definition::Distance { start, end } => {
                for anchor in [start, end] {
                    anchor.validate()?;
                }
            }
            Definition::Angle { start, vertex, end } => {
                for anchor in [start, vertex, end] {
                    anchor.validate()?;
                }
            }
        }
        Ok(())
    }
}
pub fn decode(value: &serde_json::Value) -> Result<Vec<Annotation>> {
    let records: Vec<Annotation> = serde_json::from_value(value.clone())?;
    if records.len() > 256 {
        return Err(Error::domain(
            "INVALID_REQUEST",
            "At most 256 saved annotations are supported",
        ));
    }
    let mut ids = std::collections::HashSet::new();
    for record in &records {
        record.validate()?;
        if !ids.insert(&record.id) {
            return Err(Error::domain(
                "INVALID_REQUEST",
                "Duplicate saved annotation ID",
            ));
        }
    }
    Ok(records)
}
/// Geometry-affecting inputs. Annotation-only edits keep these identical so a
/// rebuild can reuse the previous publication without executing source.
pub(crate) fn same_geometry_inputs(a: &Inputs, b: &Inputs) -> bool {
    a.files == b.files
        && a.parameters == b.parameters
        && a.mechanism == b.mechanism
        && a.entry_point == b.entry_point
        && a.assets == b.assets
        && a.dependencies == b.dependencies
}
/// Reproject saved annotations onto an already-published model. Returns `None`
/// when an anchor needs live BRep that is not present in the publication.
pub(crate) fn reproject(records: &[Annotation], model: &Value) -> Result<Option<Value>> {
    let published = model["annotations"]
        .as_array()
        .cloned()
        .unwrap_or_default();
    let mut saved = Vec::with_capacity(records.len());
    for record in records {
        match resolve_one(record, model, &published)? {
            Some(item) => saved.push(item),
            None => return Ok(None),
        }
    }
    // Keep published/automatic rows, but drop automatic diameters the worker
    // would suppress once a matching saved diameter is present.
    let mut output = published
        .iter()
        .filter(|item| item.get("saved_id").is_none())
        .filter(|item| !suppressed_automatic(item, &saved))
        .cloned()
        .collect::<Vec<_>>();
    output.extend(saved);
    Ok(Some(Value::Array(output)))
}
fn suppressed_automatic(item: &Value, saved: &[Value]) -> bool {
    if item.get("automatic") != Some(&Value::Bool(true)) || item["kind"] != "diameter" {
        return false;
    }
    let (Some(part), Some(start), Some(end)) =
        (item.get("part"), item.get("start"), item.get("end"))
    else {
        return false;
    };
    saved.iter().any(|other| {
        other.get("saved_id").is_some()
            && other["kind"] == "diameter"
            && other.get("part") == Some(part)
            && point_close(other.get("start"), Some(start))
            && point_close(other.get("end"), Some(end))
    })
}
fn point_close(a: Option<&Value>, b: Option<&Value>) -> bool {
    let (Some(a), Some(b)) = (a.and_then(|v| v.as_array()), b.and_then(|v| v.as_array())) else {
        return false;
    };
    if a.len() != 3 || b.len() != 3 {
        return false;
    }
    (0..3).all(|i| {
        let (Some(x), Some(y)) = (a[i].as_f64(), b[i].as_f64()) else {
            return false;
        };
        (x - y).abs() < 1e-7
    })
}
fn resolve_one(record: &Annotation, model: &Value, published: &[Value]) -> Result<Option<Value>> {
    let mut item = json!({
        "id": format!("saved:{}", record.id),
        "saved_id": record.id,
        "label": record.label,
        "kind": match &record.definition {
            Definition::Distance { .. } => "distance",
            Definition::Angle { .. } => "angle",
            Definition::Overall { .. } => "overall",
            Definition::Radius { .. } => "radius",
            Definition::Diameter { .. } => "diameter",
            Definition::Published { .. } => "published",
            Definition::GeometryCircle { measure, .. } => match measure {
                CircleMeasure::Radius => "radius",
                CircleMeasure::Diameter => "diameter",
            },
        },
        "definition": record.definition,
        "format": record.format,
        "label_offset": record.label_offset,
        "parameter": record.parameter,
        "unit": "mm",
        "status": "resolved",
        "accuracy": "exact",
    });
    let resolved = match &record.definition {
        Definition::Published { publication_id } => {
            let source = published.iter().find(|item| item["id"] == *publication_id);
            let Some(source) = source else {
                return Ok(Some(broken(
                    item,
                    "BROKEN_ANCHOR",
                    "Published dimension no longer exists",
                )));
            };
            for key in ["part", "start", "end", "value", "kind", "unit"] {
                if let Some(value) = source.get(key) {
                    item[key] = value.clone();
                }
            }
            if source["kind"] == "angle" {
                item["vertex"] = source["vertex"].clone();
                item["vertex_part"] = source["part"].clone();
            }
            item["end_part"] = source["part"].clone();
            if item["parameter"].is_null() {
                item["parameter"] = source.get("parameter").cloned().unwrap_or(Value::Null);
            }
            item
        }
        Definition::Overall { instance_id, axis } => {
            let Some(part) = part(model, instance_id) else {
                return Ok(Some(broken(
                    item,
                    "BROKEN_ANCHOR",
                    &format!("Missing instance {instance_id}"),
                )));
            };
            let bounds = &part["bounds"];
            let index = match axis {
                Axis::X => 0,
                Axis::Y => 1,
                Axis::Z => 2,
            };
            let start = bounds["min"].clone();
            let mut end = bounds["min"].clone();
            end[index] = bounds["max"][index].clone();
            item["part"] = json!(instance_id);
            item["end_part"] = json!(instance_id);
            item["start"] = start;
            item["end"] = end;
            item["value"] = bounds["size"][index].clone();
            item["kind"] = json!("overall");
            item
        }
        Definition::Distance { start, end } => {
            let start_resolved = anchor(model, start, published)?;
            let end_resolved = anchor(model, end, published)?;
            let (Some((part, start_point)), Some((end_part, end_point))) =
                (start_resolved, end_resolved)
            else {
                if let Some(prior) = prior_saved(published, record) {
                    return Ok(Some(reuse_prior(item, prior)));
                }
                return Ok(None);
            };
            let world_start = world_point(model, &part, start_point);
            let world_end = world_point(model, &end_part, end_point);
            item["part"] = json!(part);
            item["end_part"] = json!(end_part);
            item["start"] = json!(start_point);
            item["end"] = json!(end_point);
            item["value"] = json!(distance(world_start, world_end));
            item["kind"] = json!("distance");
            item
        }
        Definition::Angle { start, vertex, end } => {
            let start_resolved = anchor(model, start, published)?;
            let vertex_resolved = anchor(model, vertex, published)?;
            let end_resolved = anchor(model, end, published)?;
            let (
                Some((part, start_point)),
                Some((vertex_part, vertex_point)),
                Some((end_part, end_point)),
            ) = (start_resolved, vertex_resolved, end_resolved)
            else {
                if let Some(prior) = prior_saved(published, record) {
                    return Ok(Some(reuse_prior(item, prior)));
                }
                return Ok(None);
            };
            let value = angle_value(
                world_point(model, &part, start_point),
                world_point(model, &vertex_part, vertex_point),
                world_point(model, &end_part, end_point),
            );
            let Some(value) = value else {
                return Ok(Some(broken(
                    item,
                    "BROKEN_ANCHOR",
                    "An angle requires two nonzero finite rays",
                )));
            };
            item["part"] = json!(part);
            item["vertex_part"] = json!(vertex_part);
            item["end_part"] = json!(end_part);
            item["start"] = json!(start_point);
            item["vertex"] = json!(vertex_point);
            item["end"] = json!(end_point);
            item["value"] = json!(value);
            item["unit"] = json!("rad");
            item
        }
        Definition::GeometryCircle {
            instance_id,
            entity,
            measure,
        } => {
            let Some(source) = published.iter().find(|item| {
                item["definition"]["kind"] == "geometry_circle"
                    && item["definition"]["instance_id"] == *instance_id
                    && item["definition"]["entity"]["sha256"] == entity.sha256
                    && item["definition"]["entity"]["entity_kind"]
                        == match entity.entity_kind {
                            GeometryKind::Face => "face",
                            GeometryKind::Edge => "edge",
                        }
            }) else {
                // Format-only edit of an already-pinned geometry circle.
                if let Some(prior) = prior_saved(published, record) {
                    return Ok(Some(reuse_prior(item, prior)));
                }
                return Ok(None);
            };
            let kind = match measure {
                CircleMeasure::Radius => "radius",
                CircleMeasure::Diameter => "diameter",
            };
            let mut value = source["value"].as_f64().unwrap_or(0.);
            if source["kind"] == "diameter" && kind == "radius" {
                value *= 0.5;
            } else if source["kind"] == "radius" && kind == "diameter" {
                value *= 2.;
            }
            item["part"] = json!(instance_id);
            item["end_part"] = json!(instance_id);
            item["start"] = source["start"].clone();
            item["end"] = source["end"].clone();
            item["value"] = json!(value);
            item["kind"] = json!(kind);
            item
        }
        Definition::Radius { .. } | Definition::Diameter { .. } => {
            if let Some(prior) = prior_saved(published, record) {
                reuse_prior(item, prior)
            } else {
                return Ok(None);
            }
        }
    };
    let angular = resolved["kind"] == "angle";
    let format_angular = matches!(record.format.unit, DisplayUnit::Deg | DisplayUnit::Rad);
    if angular != format_angular {
        return Ok(Some(broken(
            resolved,
            "BROKEN_ANCHOR",
            "Angle display requires deg/rad; length display requires mm/cm/m/in",
        )));
    }
    if let Some(parameter) = record.parameter.as_deref() {
        let unit = model["parameters"][parameter]["unit"].as_str();
        let allowed = if angular {
            matches!(unit, Some("deg" | "rad"))
        } else {
            unit == Some("mm")
        };
        if !allowed {
            return Ok(Some(broken(
                resolved,
                "BROKEN_ANCHOR",
                "Dimension parameter binding must reference a published parameter with matching length/angle units",
            )));
        }
    }
    Ok(Some(resolved))
}
/// Prior publication of the same saved definition (format/label edits only).
fn prior_saved<'a>(published: &'a [Value], record: &Annotation) -> Option<&'a Value> {
    let definition = serde_json::to_value(&record.definition).ok()?;
    published.iter().find(|item| {
        item["saved_id"] == record.id
            && item["definition"] == definition
            && item["status"] != "broken"
            && item.get("value").is_some()
            && item.get("start").is_some()
            && item.get("end").is_some()
            && item.get("part").is_some()
    })
}
fn reuse_prior(mut item: Value, prior: &Value) -> Value {
    for key in [
        "part",
        "end_part",
        "vertex_part",
        "start",
        "end",
        "vertex",
        "value",
        "kind",
        "unit",
    ] {
        if let Some(value) = prior.get(key) {
            item[key] = value.clone();
        }
    }
    item
}
fn broken(mut item: Value, code: &str, message: &str) -> Value {
    for key in [
        "value",
        "start",
        "end",
        "part",
        "end_part",
        "vertex",
        "vertex_part",
    ] {
        if let Some(object) = item.as_object_mut() {
            object.remove(key);
        }
    }
    item["status"] = json!("broken");
    item["error"] = json!({"code": code, "message": message});
    item
}
fn part<'a>(model: &'a Value, instance: &str) -> Option<&'a Value> {
    model["parts"]
        .as_array()?
        .iter()
        .find(|part| part["instance_id"] == instance)
}
fn anchor(
    model: &Value,
    definition: &Anchor,
    _published: &[Value],
) -> Result<Option<(String, [f64; 3])>> {
    match definition {
        Anchor::LocalPoint { instance_id, point } => {
            if part(model, instance_id).is_none() {
                return Ok(None);
            }
            Ok(Some((instance_id.clone(), *point)))
        }
        Anchor::Bounds {
            instance_id,
            fraction,
        } => {
            let Some(part) = part(model, instance_id) else {
                return Ok(None);
            };
            let min = [
                part["bounds"]["min"][0].as_f64().unwrap_or(0.),
                part["bounds"]["min"][1].as_f64().unwrap_or(0.),
                part["bounds"]["min"][2].as_f64().unwrap_or(0.),
            ];
            let size = [
                part["bounds"]["size"][0].as_f64().unwrap_or(0.),
                part["bounds"]["size"][1].as_f64().unwrap_or(0.),
                part["bounds"]["size"][2].as_f64().unwrap_or(0.),
            ];
            Ok(Some((
                instance_id.clone(),
                [
                    min[0] + fraction[0] * size[0],
                    min[1] + fraction[1] * size[1],
                    min[2] + fraction[2] * size[2],
                ],
            )))
        }
        // Geometry/feature centers need live BRep; callers reuse a prior saved
        // publication when the definition is unchanged, otherwise fall through.
        Anchor::GeometryCenter { .. } | Anchor::FeatureCenter { .. } => Ok(None),
    }
}
fn world_point(model: &Value, instance: &str, point: [f64; 3]) -> [f64; 3] {
    let position = part(model, instance)
        .and_then(|part| part.get("position"))
        .and_then(|value| value.as_array())
        .map(|value| {
            [
                value.first().and_then(|v| v.as_f64()).unwrap_or(0.),
                value.get(1).and_then(|v| v.as_f64()).unwrap_or(0.),
                value.get(2).and_then(|v| v.as_f64()).unwrap_or(0.),
            ]
        })
        .unwrap_or([0., 0., 0.]);
    [
        point[0] + position[0],
        point[1] + position[1],
        point[2] + position[2],
    ]
}
fn distance(a: [f64; 3], b: [f64; 3]) -> f64 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}
fn angle_value(start: [f64; 3], vertex: [f64; 3], end: [f64; 3]) -> Option<f64> {
    let a = [start[0] - vertex[0], start[1] - vertex[1], start[2] - vertex[2]];
    let b = [end[0] - vertex[0], end[1] - vertex[1], end[2] - vertex[2]];
    let la = (a[0].powi(2) + a[1].powi(2) + a[2].powi(2)).sqrt();
    let lb = (b[0].powi(2) + b[1].powi(2) + b[2].powi(2)).sqrt();
    if la.min(lb) <= 1e-9 || !(la + lb).is_finite() {
        return None;
    }
    let a = [a[0] / la, a[1] / la, a[2] / la];
    let b = [b[0] / lb, b[1] / lb, b[2] / lb];
    let cross = [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    ];
    Some((cross[0].powi(2) + cross[1].powi(2) + cross[2].powi(2)).sqrt().atan2(a[0] * b[0] + a[1] * b[1] + a[2] * b[2]))
}
impl Core {
    pub async fn edit_annotation(
        &self,
        workspace: &str,
        base: &str,
        annotation_id: &str,
        record: Option<Annotation>,
        actor: &str,
    ) -> Result<Job> {
        self.ensure_actor_active(actor)?;
        identifier(annotation_id)?;
        if let Some(record) = &record {
            record.validate()?;
            if record.id != annotation_id {
                return Err(Error::domain(
                    "INVALID_REQUEST",
                    "Annotation ID differs from record",
                ));
            }
        }
        let draft = {
            let mut workspaces = self.workspaces.lock().await;
            let ws = workspaces
                .get_mut(workspace)
                .ok_or_else(|| Error::domain("APP_UNAVAILABLE", "Unknown workspace"))?;
            if ws.stored.current != base {
                return Err(Error::domain(
                    "REVISION_CONFLICT",
                    "Expected revision no longer current",
                ));
            }
            let mut inputs = ws.stored.revisions[base].inputs.clone();
            let mut records = decode(&inputs.annotations)?;
            let index = records.iter().position(|item| item.id == annotation_id);
            match (index, record) {
                (Some(index), Some(record)) => records[index] = record,
                (None, Some(record)) => records.push(record),
                (Some(index), None) => {
                    records.remove(index);
                }
                (None, None) => {
                    return Err(Error::domain("INVALID_REQUEST", "Unknown saved annotation"));
                }
            }
            inputs.annotations = serde_json::to_value(records)?;
            decode(&inputs.annotations)?;
            let draft = Draft {
                id: id(),
                base_revision: base.into(),
                source_hashes: inputs
                    .files
                    .iter()
                    .map(|(path, source)| (path.clone(), hash(source)))
                    .collect(),
                inputs,
                actor: actor.into(),
                external_fingerprint: None,
                python_origin: None,
                restore_revision: None,
            };
            let mut next = ws.stored.clone();
            next.drafts.insert(draft.id.clone(), draft.clone());
            self.persist(&next).await?;
            ws.stored = next;
            draft
        };
        self.build(workspace, base, &draft.id, actor).await
    }
}
